(function(root,factory){const api=factory();if(typeof module==='object')module.exports=api;else root.MartinsBackup=api;})(globalThis,()=>{'use strict';
const owned=k=>/^(cm_|martins_|cronograma_v2_|itens_medicao_v2_)/.test(k);
const canonical=entries=>JSON.stringify([...entries].sort((a,b)=>a.key<b.key?-1:a.key>b.key?1:0));
async function digest(entries){const hash=await crypto.subtle.digest('SHA-256',new TextEncoder().encode(canonical(entries)));return Array.from(new Uint8Array(hash),b=>b.toString(16).padStart(2,'0')).join('');}
async function create(storage,defaults={}){const items=new Map();for(let i=0;i<storage.length;i++){const key=storage.key(i);if(owned(key))items.set(key,storage.getItem(key));}for(const [key,value] of Object.entries(defaults))if(owned(key)&&!items.has(key))items.set(key,JSON.stringify(value));const entries=[...items].map(([key,value])=>({key,value}));return {format:'martins-backup',version:3,createdAt:new Date().toISOString(),entries,sha256:await digest(entries)};}
async function validate(input){const backup=typeof input==='string'?JSON.parse(input):input;if(backup?.format!=='martins-backup'||backup.version!==3||!Array.isArray(backup.entries)||typeof backup.sha256!=='string')throw Error('Formato de backup não reconhecido');const keys=new Set();for(const item of backup.entries){if(!item||typeof item.key!=='string'||!owned(item.key)||typeof item.value!=='string'||keys.has(item.key))throw Error('Chave inválida ou duplicada no backup');keys.add(item.key);}if(await digest(backup.entries)!==backup.sha256)throw Error('Integridade inválida: o conteúdo do backup mudou');return backup;}
async function restoreEmpty(storage,input){const backup=await validate(input);for(let i=0;i<storage.length;i++)if(owned(storage.key(i)))throw Error('Restauração exige destino vazio; nenhum cadastro pode ser sobrescrito');const written=[];try{for(const {key,value} of backup.entries){storage.setItem(key,value);written.push({key,value});}}catch(e){for(const {key,value} of written.reverse())if(storage.getItem(key)===value)storage.removeItem(key);throw Error('Restauração interrompida; destino revertido: '+e.message);}return backup.entries.length;}
return {create,validate,restoreEmpty,owned};});
